WITH rels AS (SELECT c.*,n.nspname FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE (n.nspname,c.relname) IN(VALUES ('private','fiscal_identity_reservations'),('public','conciliacao_execucoes'),('public','conciliacao_resultados'),('public','exposicao_execucoes'),('public','exposicao_overlay_itens'),('public','fundos'),('public','importacoes_financeiras'),('public','logs_auditoria'),('public','nfe_fiscal_consultas'),('public','nfe_fiscal_eventos'),('public','nfe_fiscal_provider_state'),('public','nfe_fiscal_snapshots'),('public','notas_fiscais'),('public','notificacoes'),('public','operacao_calculo_nfs'),('public','operacoes'),('public','plataforma_auditoria'),('public','profiles'),('public','remessa_operacional_chaves'),('public','usuario_papeis'),('public','cedente_fundos'),('public','operacoes_nfs'),('public','sacado_acessos'),('public','sacados'),('public','nfe_fiscal_execucoes'),('public','nfe_fiscal_execucao_eventos'),('private','nfe_fiscal_http_attempts'))),
funcs AS (SELECT p.*,n.nspname FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname||'.'||p.proname IN('auth.uid','auth.jwt','extensions.digest','private.nfe_chave_valida_v1','private.financeiro_gestor_tem_acesso_fundo','private.usuario_e_super_admin','private.c1_1_usuario_e_super_admin_rls','public.obter_sessao_mfa_atual','public.solicitar_reconsulta_nfe_fiscal','public.nfe_fiscal_claim','public.obter_situacao_fiscal_nfe','private.nfe_enfileirar_apos_submissao','private.operacao_status_reserva_nf','private.sacado_tem_acesso_cnpj_fundo','private.sacado_tem_acesso_operacao','private.sacado_tem_acesso_operacao_nf','public.persistir_exposicao_execucao','public.processar_aceite_sacado','public.diagnosticar_variacao_estoques','public.persistir_conciliacao_execucao','public.nfe_fiscal_complete','public.nfe_fiscal_fail','private.sacado_vinculos_autorizados','private.sacado_contexto'))
SELECT jsonb_build_object(
'observed_at_utc',statement_timestamp() AT TIME ZONE 'UTC','database',current_database(),'read_only',current_setting('transaction_read_only'),
'relations',(SELECT jsonb_agg(jsonb_build_object('schema',r.nspname,'name',r.relname,'kind',r.relkind,'owner',pg_get_userbyid(r.relowner),'rls',r.relrowsecurity,'force_rls',r.relforcerowsecurity,
'columns',(SELECT jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'not_null',a.attnotnull,'default',pg_get_expr(d.adbin,d.adrelid),'identity',a.attidentity,'generated',a.attgenerated) ORDER BY a.attnum) FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attrelid=r.oid AND a.attnum>0 AND NOT a.attisdropped),
'acl',(SELECT jsonb_agg(jsonb_build_object('grantee',CASE WHEN x.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(x.grantee) END,'grantor',pg_get_userbyid(x.grantor),'privilege',x.privilege_type,'grantable',x.is_grantable) ORDER BY x.grantee,x.privilege_type,x.grantor) FROM aclexplode(COALESCE(r.relacl,acldefault('r',r.relowner))) x),
'constraints',(SELECT jsonb_agg(jsonb_build_object('name',c.conname,'type',c.contype,'validated',c.convalidated,'definition',pg_get_constraintdef(c.oid,true),'referenced',CASE WHEN c.confrelid=0 THEN NULL ELSE c.confrelid::regclass::text END,'columns',(SELECT jsonb_agg(a.attname ORDER BY k.ord) FROM unnest(c.conkey) WITH ORDINALITY k(num,ord) JOIN pg_attribute a ON a.attrelid=c.conrelid AND a.attnum=k.num)) ORDER BY c.conname) FROM pg_constraint c WHERE c.conrelid=r.oid),
'indexes',(SELECT jsonb_agg(jsonb_build_object('name',ci.relname,'definition',pg_get_indexdef(i.indexrelid),'constraint_index',EXISTS(SELECT 1 FROM pg_constraint co WHERE co.conindid=i.indexrelid),'valid',i.indisvalid) ORDER BY ci.relname) FROM pg_index i JOIN pg_class ci ON ci.oid=i.indexrelid WHERE i.indrelid=r.oid),
'policies',(SELECT jsonb_agg(jsonb_build_object('name',p.polname,'command',p.polcmd,'permissive',p.polpermissive,'roles',(SELECT jsonb_agg(CASE WHEN role_id=0 THEN 'PUBLIC' ELSE pg_get_userbyid(role_id) END ORDER BY role_id) FROM unnest(p.polroles) role_id),'using',pg_get_expr(p.polqual,p.polrelid),'check',pg_get_expr(p.polwithcheck,p.polrelid)) ORDER BY p.polname) FROM pg_policy p WHERE p.polrelid=r.oid),
'triggers',(SELECT jsonb_agg(jsonb_build_object('name',t.tgname,'enabled',t.tgenabled,'definition',pg_get_triggerdef(t.oid,true)) ORDER BY t.tgname) FROM pg_trigger t WHERE t.tgrelid=r.oid AND NOT t.tgisinternal)
) ORDER BY r.nspname,r.relname) FROM rels r),
'functions',(SELECT jsonb_agg(jsonb_build_object('schema',p.nspname,'name',p.proname,'arguments',pg_get_function_identity_arguments(p.oid),'owner',pg_get_userbyid(p.proowner),'definer',p.prosecdef,'config',p.proconfig,'language',(SELECT lanname FROM pg_language WHERE oid=p.prolang),
'suspected_secret',pg_get_functiondef(p.oid) ~ 'eyJ[A-Za-z0-9_-]{15,}[.][A-Za-z0-9_-]{15,}[.][A-Za-z0-9_-]{10,}|sk-(proj-)?[A-Za-z0-9_-]{20,}|-----BEGIN [A-Z ]*PRIVATE KEY-----',
'definition',CASE WHEN pg_get_functiondef(p.oid) !~ 'eyJ[A-Za-z0-9_-]{15,}[.][A-Za-z0-9_-]{15,}[.][A-Za-z0-9_-]{10,}|sk-(proj-)?[A-Za-z0-9_-]{20,}|-----BEGIN [A-Z ]*PRIVATE KEY-----' THEN encode(sha256(convert_to(replace(pg_get_functiondef(p.oid),E'\r\n',E'\n'),'UTF8')),'hex') END,
'acl',(SELECT jsonb_agg(jsonb_build_object('grantee',CASE WHEN x.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(x.grantee) END,'grantor',pg_get_userbyid(x.grantor),'privilege',x.privilege_type,'grantable',x.is_grantable) ORDER BY x.grantee,x.privilege_type,x.grantor) FROM aclexplode(COALESCE(p.proacl,acldefault('f',p.proowner))) x)
) ORDER BY p.nspname,p.proname,pg_get_function_identity_arguments(p.oid)) FROM funcs p),
'schemas',(SELECT jsonb_agg(jsonb_build_object('name',n.nspname,'owner',pg_get_userbyid(n.nspowner),'acl',(SELECT jsonb_agg(jsonb_build_object('grantee',CASE WHEN x.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(x.grantee) END,'grantor',pg_get_userbyid(x.grantor),'privilege',x.privilege_type,'grantable',x.is_grantable) ORDER BY x.grantee,x.privilege_type,x.grantor) FROM aclexplode(COALESCE(n.nspacl,acldefault('n',n.nspowner))) x))) FROM pg_namespace n WHERE n.nspname IN ('public','private','auth','extensions'))
) AS catalog;
